def erase_overlap_intervals(intervals):
    intervals.sort(key=lambda iv: iv[1])   # earliest end leaves the most room
    kept, prev_end = 0, float('-inf')
    for start, end in intervals:
        if start >= prev_end:
            kept += 1
            prev_end = end
    return len(intervals) - kept

P10-minimum-number-of-arrows-to-burst-ba:
def find_min_arrow_shots(points):
    points.sort()
    arrows, reach = 0, float('-inf')   # reach = smallest end in the current group
    for start, end in points:
        if start > reach:              # shares no point with the group: new arrow
            arrows += 1
            reach = end
        else:
            reach = min(reach, end)    # the shared window shrinks
    return arrows

