def min_meeting_rooms(intervals):
    starts = sorted(s for s, _ in intervals)
    ends = sorted(e for _, e in intervals)
    rooms = j = 0
    for s in starts:
        if s >= ends[j]:               # some meeting has ended: take its room
            j += 1
        else:
            rooms += 1                 # everyone is still busy: open a room
    return rooms

